exports.debounce=function(fn,delay,scheduler) {
  let timer,args;
  function run() { timer=undefined; return fn(...args); }
  function wrapped(...values) {
    args=values;
    if(timer) scheduler.clear(timer);
    timer=scheduler.set(run,delay);
  }
  wrapped.flush=()=>timer ? run() : undefined;
  wrapped.cancel=()=>{if(timer) scheduler.clear(timer); timer=undefined;};
  return wrapped;
};

