const test=require('node:test');
const assert=require('node:assert/strict');
const {debounce}=require('../debounce.cjs');
function clock() {
  let next=0;
  const jobs=new Map();
  return {set(fn,delay){assert.equal(delay,5);const id=next++;jobs.set(id,fn);return id;},
    clear(id){jobs.delete(id);},size(){return jobs.size;},
    tick(){const list=[...jobs.values()];jobs.clear();for(const fn of list)fn();}};
}
test('latest receiver, zero handle and flush',()=>{
  const scheduler=clock(),calls=[];
  const fn=debounce(function(value){calls.push([this.name,value]);return value*2;},5,scheduler);
  assert.equal(fn.call({name:'old'},1),undefined);
  fn.call({name:'new'},3);
  assert.equal(scheduler.size(),1);
  assert.equal(fn.flush(),6);
  assert.deepEqual(calls,[['new',3]]);
  assert.equal(fn.flush(),undefined);
  scheduler.tick();
  assert.equal(calls.length,1);
});
test('cancel initial zero handle and reentrant scheduling',()=>{
  const scheduler=clock(),calls=[];
  const fn=debounce(value=>{calls.push(value);if(value===1)fn(2);},5,scheduler);
  fn(8);fn.cancel();scheduler.tick();
  assert.deepEqual(calls,[]);
  fn(1);scheduler.tick();
  assert.deepEqual(calls,[1]);
  assert.equal(scheduler.size(),1);
  scheduler.tick();
  assert.deepEqual(calls,[1,2]);
  fn.cancel();fn.cancel();
});

