exports.debounce=function(fn,delay,scheduler) {
  let timer, pending=false, args, receiver;
  function run() {
    if(!pending) return undefined;
    const callArgs=args, callReceiver=receiver;
    pending=false; timer=undefined; args=receiver=undefined;
    return fn.apply(callReceiver,callArgs);
  }
  function wrapped(...values) {
    if(pending) scheduler.clear(timer);
    args=values; receiver=this; pending=true;
    timer=scheduler.set(run,delay);
  }
  wrapped.flush=()=>{
    if(!pending) return undefined;
    scheduler.clear(timer);
    return run();
  };
  wrapped.cancel=()=>{
    if(pending) scheduler.clear(timer);
    pending=false; timer=undefined; args=receiver=undefined;
  };
  return wrapped;
};

